import urllib.request
import urllib.error
import time
from typing import Optional

class RateLimitError(Exception):
    """Raised when the API returns HTTP 429 (Too Many Requests)."""
    pass

class ServerError(Exception):
    """Raised when the API returns an HTTP 5xx error after retry."""
    pass

class ClientError(Exception):
    """Raised when the API returns an HTTP 4xx error (except 429)."""
    pass

class ConnectionError(Exception):
    """Raised when a network error occurs after retry."""
    pass

class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def _make_request(self, path: str, retries: int, delay: float) -> str:
        url = self.base_url.rstrip('/') + path.lstrip('/')
        for attempt in range(retries):
            try:
                req = urllib.request.Request(url, method='GET')
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if attempt == retries - 1:
                        raise RateLimitError(f"Rate limited (429) after {retries} attempts")
                    time.sleep(delay)
                elif 500 <= e.code < 600:
                    if attempt == retries - 1:
                        raise ServerError(f"Server error {e.code} after {retries} attempts")
                    time.sleep(delay)
                else:
                    raise ClientError(f"Client error {e.code}: {e.reason}")
            except urllib.error.URLError as e:
                if attempt == retries - 1:
                    raise ConnectionError(f"Connection failed: {e.reason}")
                time.sleep(delay)
            except Exception as e:
                raise RuntimeError(f"Unexpected error: {e}")

    def get(self, path: str) -> str:
        # 429: up to 3 retries with exponential backoff 0.5, 1, 2
        # 5xx: 1 retry after 1s
        # network: 1 retry after 1s
        # 4xx (non-429): no retry
        return self._make_request(path, retries=3, delay=0.5)
